-- Ir a la ventana N del grupo activo

for i = 1, 8 do
    hl.bind(mainMod .. " + ALT + " .. i, hl.dsp.group.active({ index = i }), { description = "go to window " .. i .. " in group" })
end

-- Escribir ñ / Ñ con teclado US (code:47 es la tecla ;)
hl.bind("CTRL + SHIFT + code:47", hl.dsp.exec_cmd("wtype ñ"), { description = "type ñ" })
hl.bind("CTRL + SHIFT + ALT + code:47", hl.dsp.exec_cmd("wtype Ñ"), { description = "type Ñ" })

-- Captura rápida del Panel (rofi)
hl.bind(mainMod .. " + K", hl.dsp.exec_cmd(os.getenv("HOME") .. "/Projects/panel-maestro/scripts/desktop/quick_capture.sh"), { description = "panel quick capture" })
-- Agenda del Panel (rofi; Super+Ctrl+K ya es «Move left into group»)
hl.bind(mainMod .. " + ALT + K", hl.dsp.exec_cmd(os.getenv("HOME") .. "/Projects/panel-maestro/scripts/desktop/panel_agenda.py --menu"), { description = "panel agenda" })

-- Modo pensando: no suspender mientras Claude Code trabaja (C de Claude; vuelve a pulsar para quitarlo)
hl.bind(mainMod .. " + ALT + C", hl.dsp.exec_cmd(scriptsDir .. "/ThinkingMode.sh"), { description = "thinking mode (no suspend)" })

